<section class="settings-page">

  <!-- ==================== Header ==================== -->

  <div class="settings-header-banner">

    <div class="settings-page__header">

      <div>
        <h2 class="settings-page__title">Settings</h2>

        <p class="settings-page__subtitle">
          Manage your application appearance and language preferences.
        </p>
      </div>

    </div>

  </div>


  <!-- ==================== Settings Content ==================== -->

  <div class="settings-card">

    <!-- ==================== Appearance ==================== -->

    <div class="settings-section">

      <div class="settings-section__header">

        <div class="settings-section__icon settings-section__icon--blue">
          <i class="fa-solid fa-palette"></i>
        </div>

        <div>

          <h3>Appearance</h3>

          <p>
            Choose how the learning center looks.
          </p>

        </div>

      </div>


      <!-- Dark Mode -->

      <div class="setting-item">

        <div class="setting-item__info">

          <div class="setting-item__title">

            <i
              class="fa-solid"
              [class.fa-moon]="!isDarkMode"
              [class.fa-sun]="isDarkMode"
            ></i>

            {{ isDarkMode ? 'Dark Mode' : 'Light Mode' }}

          </div>

          <p>
            {{ isDarkMode
              ? 'Dark theme is currently enabled.'
              : 'Light theme is currently enabled.'
            }}
          </p>

        </div>


        <!-- Toggle -->

        <label class="switch">

          <input
            type="checkbox"
            [(ngModel)]="isDarkMode"
            (change)="toggleDarkMode()"
          />

          <span class="slider"></span>

        </label>

      </div>

    </div>


    <!-- ==================== Language ==================== -->

    <div class="settings-section">

      <div class="settings-section__header">

        <div class="settings-section__icon settings-section__icon--purple">
          <i class="fa-solid fa-language"></i>
        </div>

        <div>

          <h3>Language</h3>

          <p>
            Choose the language used throughout the application.
          </p>

        </div>

      </div>


      <!-- Language -->

      <div class="setting-item">

        <div class="setting-item__info">

          <div class="setting-item__title">

            <i class="fa-solid fa-globe"></i>

            Application Language

          </div>

          <p>
            Select your preferred language.
          </p>

        </div>


        <div class="language-select">

          <select
            [(ngModel)]="selectedLanguage"
            (change)="changeLanguage()"
          >

            <option value="en">
              🇬🇧 English
            </option>

            <option value="ar">
              🇪🇬 العربية
            </option>

          </select>

        </div>

      </div>

    </div>


    <!-- ==================== Current Settings ==================== -->

    <div class="settings-footer">

      <div class="current-settings">

        <i class="fa-solid fa-circle-check"></i>

        <span>
          Settings are saved automatically.
        </span>

      </div>

    </div>

  </div>

</section>
